            'security.desc': 'TOS 协调由不同业主运营的模型服务，同时让敏感任务留在客户控制的本地、私有或本地部署节点。网络负责证据与价值结算，而不要求集中托管专有数据集。',
            'security.card1Title': '本地优先执行',
            'security.card1Desc': '敏感任务可以被限制在获批的本地、私有或边缘节点。只有客户策略允许时，请求才会向外路由。',
            'security.card2Title': '最小必要披露',
            'security.card2Desc': '服务描述符只公开能力和交易条件，而非无限制访问权。任务策略约束载荷、工具、端点、预算和数据保留。',
            'security.card3Title': '证明结果，不公开秘密',
            'security.card3Desc': '私密提示词、数据集和输出不上链。签名凭证、哈希和证据引用在不公开底层内容的情况下提供可问责性。',
            'security.card4Title': '没有单一公司的控制点',
            'security.card4Desc': '多元提供方、联邦注册中心和业主自营节点，降低对单一公司、地区或平台政策的依赖。如果一条路径故障或拒绝服务，智能体可以发现符合策略的替代能力。',
            'security.boundaryTitle': '设计目标是减少数据暴露，而不是作出不可能的绝对保证。',
            'security.boundaryDesc': '安全性仍取决于节点加固、加密、访问控制、可信运行时和运营规范。高度敏感的任务应始终留在客户明确批准和控制的节点上。',

            'vision.kicker': '一张网络，两条前沿',
            'vision.title': '数字服务，物理智能。',
            'vision.desc': '协调、结算与信任，居于独立拥有的供给与全球需求之间。',
            'vision.hint': '滑动查看完整架构栈 →',

            'edge.kicker': '物理 AI 的切入点',
            'edge.title': '不是最大的边缘，而是对的那一个。',
            'edge.lede': '部署在摄像头、机器人、车辆或产线旁的终端，可以在远程云面临延迟、带宽、隐私、连接性或安全约束的场景下执行任务。',
            'edge.desc': 'TOS 把这些设备当作场地绑定的服务终端，而不是缩小版的 GPU 云。本地实时工作和独立的安全控制，始终优先于外部网络任务。',
            'edge.link': '阅读物理 AI 架构',
            'edge.card1Title': '按设计支持断网运行',
            'edge.card1Desc': '已批准的本地工作负载在离线时仍可继续，凭借有界授权，在重新连接后进行幂等的状态对账。',
            'edge.card2Title': '实时工作优先',
            'edge.card2Desc': '安全联锁、控制截止时间与本地感知，优先于外部服务和后台任务。',
            'edge.card3Title': '更新失败也安全',
            'edge.card3Desc': '签名的构件、兼容性关卡、分阶段灰度发布、健康检查与已知良好版本回滚，共同保护设备群。',
            'edge.card4Title': '执行保持隔离',
            'edge.card4Desc': '没有公共 shell、裸执行器访问、Docker socket 或不受限的主机权限。每一条队列和每一份资源都有边界。',

            'flywheel.kicker': '网络为何能够复合增长',
            'flywheel.title': '每一笔交易都让下一笔更容易。',
            'flywheel.desc': 'TOS 的设计围绕累积的互操作性展开，而不是奖励闲置硬件。更多兼容的服务改善选择；更多需求提升提供方利用率；更多签名凭证带来更好的运营证据；共享的一致性规范降低了跨设备、模型、场地和行业的集成成本。',
