            'economics.kicker': '固定供应政策',
            'economics.title': '固定总量，仅由验证者发行。',
            'economics.desc': 'TOS 的最大总发行量固定为 500,000,000 枚。暂定的 101,000 TOS 创世验证者启动分配包含在该总量内；剩余 499,899,000 TOS 只能由当选验证者生产最终确认区块并通过协议奖励路径发行。服务工作、Provider 声明和链下评分都不能创造 TOS。',
            'economics.metric1Label': '固定最大总发行量',
            'economics.metric1Value': '5 亿 TOS',
            'economics.metric1Desc': '覆盖创世发行和此后每笔验证者奖励的共识硬上限。',
            'economics.metric2Label': '临时创世分配',
            'economics.metric2Value': '101,000 TOS',
            'economics.metric2Desc': '10 万启动资金，加上两笔各 500 TOS 的系统储备。',
            'economics.metric3Label': '创世后验证者发行',
            'economics.metric3Value': '499,899,000 TOS',
            'economics.metric3Desc': '仅随最终确认区块产生；参考分发周期约为七年。',
            'economics.metric4Label': '内部人分配',
            'economics.metric4Value': '0 TOS',
            'economics.metric4Desc': '没有团队、投资者、基金会、生态或国库分配。',
            'economics.card1Label': '验证者奖励如何产生',
            'economics.card1Title': '出块为被选举的验证者集合提供资金。',
            'economics.flow1': '已出块',
            'economics.flow3': '选举人奖励池',
            'economics.flow4': '有效权益份额',
            'economics.card1Desc': '没有最终确认的区块，就没有原生创造。中断不会产生奖励债务、追赶倍数或事后补发。交易与服务费用转移的是已有的 TOS，并在出块停止后依然可以继续。',
            'economics.card2Label': '创世如何被约束',
            'economics.card2Title': '启动钱包是临时的。',
            'economics.card2Desc': '四个初始验证者以相等的共识权重开始。每个控制钱包最多可获得 2 万 TOS 的质押本金，外加不超过 100 TOS 的已计量启动成本。在连续两届当选集合成功交接之后，主钱包的剩余余额必须被销毁，其可支出余额降为零。',
            'economics.card3Label': '集中度如何被约束',
            'economics.card3Title': '公开选举取代行政式分配。',
            'economics.card3Desc': '均等的启动资金、初始为 1 的有效权益系数、提交质押上限、周期性选举、运营者控制权披露，以及公开的集中度指标，共同用于降低单一主体的主导地位。四个验证者的集合只是启动阶段的最低要求；公开参与目标是 64 个独立运营者，长期目标是至少 75 个合格验证者。',
            'economics.card4Label': '发行如何终止',
            'economics.card4Title': '达到固定上限时停止创造。',
            'economics.card4Desc': '创世发行和此后每笔验证者区块奖励都计入 5 亿枚上限。治理只能调整奖励速度和时间，不能授权超过上限的原生发行；ConfigParam 14 必须逐步降至零，或在剩余供应额度处截断。',
            'economics.disclosureTitle': '分发机制能够降低集中度风险，但无法保证所有权的分散。',
            'economics.disclosureDesc': '早期奖励必然流向当时已当选的验证者，而与质押成比例的奖励可能会放大既有持仓。TOS 不提供股权、债权、分红、赎回、固定收益、流动性或价格支撑。市场价值可能下跌，参与本身也受技术、托管、治理、集中度与监管等多重风险影响。',
            'economics.disclosureLink': '阅读完整的代币经济学',

