            'diligence.kicker': '核实工作本身，而不是形容词',
            'diligence.title': '每一个论断，都有代码支撑。',
            'diligence.desc': 'TOS 不要求认真的投资者把愿景和已交付的东西混为一谈。从源码开始，检视现有的基础设施，再评估服务与终端路线图能否把它变成一个定义类别的网络。',
