            'a2a.eyebrow': 'シェアを奪い合うのではなく、誰もが経由するレイヤーを作る。',
            'a2a.tagline': '一人の創業者。一つのエージェント。世界規模の店舗。🌍',
            'a2a.kicker': 'A2Aエコノミー',
            'a2a.title': '経済の一部ではなく、その決済レイヤーになる。',
            'a2a.desc': 'エージェント対エージェントの商取引に必要なのは、20年前に人間のEコマースが必要としたものとまったく同じです。独立した売り手と買い手が、デフォルトで取引するに足る信頼を寄せる、一つの中立的な場所です。Amazonは単なるマーケットプレイスであることに満足せず、「そのマーケットプレイス」そのものになりました。そのレールは、競合他社が追いつけない速度で複利的に成長しました。TOSはマシン商取引に対して同じ野心を持って設計されています——A2Aエコノミーの一参加者としてではなく、そのアイデンティティ・見積もり・証跡・決済のレイヤーとして、あらゆるエージェント対エージェントの取引がデフォルトで経由するインフラとして。',
