            'flywheel.node4Title': '標準',
            'flywheel.node4Desc': '統合コストの低減',
            'flywheel.leverage1Label': '資本構造',
            'flywheel.leverage1Title': 'アプリケーション層はアセットライト',
            'flywheel.leverage1Desc': 'プロバイダーがハードウェアに出資し、運用します。TOSは市場アクセス、コミットメント、決済を調整します。',
            'flywheel.leverage2Label': '拡張のロジック',
            'flywheel.leverage2Title': '一つの基盤プロトコル、複数の垂直領域',
            'flywheel.leverage2Desc': 'AIがネットワークを開き、ストレージ・商取引・ツール・対人サービスも同じ信頼のレールを再利用できます。',
            'flywheel.leverage3Label': '防御可能性',
            'flywheel.leverage3Title': '統合の深さが複利的に積み上がる',
            'flywheel.leverage3Desc': 'アイデンティティ、ポリシー、証跡、適合性、運用履歴は、エンドポイントとハードウェアの世代をまたいで引き継がれます。',

            'foundation.kicker': '実行に裏づけられた信頼性',
            'foundation.title': '稼働しているインフラ。あいまいな境界はない。',
            'foundation.desc': 'ブロックチェーンとネットワーキングの基盤は、今日すでにオープンソースとして存在します。サービスプロトコル層と端末製品層は意図的に分離されており、次の提供対象として明確に位置づけられています。',
            'foundation.implementedLabel': '実装済みの基盤',
