            'economics.kicker': '固定供給ポリシー',
            'economics.title': '供給量は固定。発行はバリデーターのみ。',
            'economics.desc': 'TOS の最大総発行量は 500,000,000 TOS に固定されています。暫定的な 101,000 TOS のジェネシス・バリデーター起動分もこの総量に含まれ、残りの 499,899,000 TOS は、選出されたバリデーターが生成する確定ブロックのプロトコル報酬としてのみ発行できます。サービス作業、プロバイダーの主張、オフチェーン採点によって TOS が作られることはありません。',
