            'economics.flow4': '有効ステーク比率',
            'economics.card1Desc': '確定したブロックがなければ、ネイティブ発行もありません。障害が発生しても、報酬債務・キャッチアップ倍率・事後補填は発生しません。取引手数料とサービス手数料は既存のTOSを移転するものであり、ブロック生成が停止した後も継続します。',
            'economics.card2Label': 'ジェネシスがどのように制約されるか',
            'economics.card2Title': 'ブートストラップウォレットは一時的なものである。',
            'economics.card2Desc': '最初の4つのバリデーターは、等しいコンセンサスウェイトで開始します。各コントロールウォレットは、2万TOSのステーク元本に加え、計測されたブートストラップコストとして最大100TOSまでを受け取ることができます。連続する2期の選出セットが成功した後、メインウォレットの残高は焼却され、使用可能残高はゼロにされなければなりません。',
            'economics.card3Label': '集中がどのように制約されるか',
            'economics.card3Title': '公開選挙が、行政的な配分に取って代わる。',
            'economics.card3Desc': '均等なブートストラップ資金、初期値1の有効ステーク係数、提出ステークの上限、繰り返される選挙、運用者の支配関係の開示、そして公開される集中度指標は、いずれも単一主体の支配を抑えるために設計されています。4バリデーターのセットは起動時の最低ラインにすぎず、公開参加の目標は独立した64の運用者、長期目標は少なくとも75の適格バリデーターです。',
            'economics.card4Label': '発行がどのように終わるか',
            'economics.card4Title': '固定上限に達した時点で発行を停止する。',
            'economics.card4Desc': 'ジェネシス発行と、その後のすべてのバリデーター・ブロック報酬は 5億 TOS の上限に算入されます。ガバナンスは報酬率と時期を調整できますが、上限を超えるネイティブ発行を承認することはできません。ConfigParam 14 はゼロへ段階的に縮小するか、残り供給枠で切り詰める必要があります。',
            'economics.disclosureTitle': '分配の仕組みは集中リスクを下げるが、所有の分散を保証するものではない。',
            'economics.disclosureDesc': '初期の報酬は必然的にその時点で選出されたバリデーターに渡り、ステークに比例した報酬は既存の保有量を複利的に増やす可能性があります。TOSは、株式、負債、配当、償還、固定利回り、流動性、価格支援のいずれも提供しません。市場価値は下落する可能性があり、参加には技術的・カストディ・ガバナンス・集中・規制上のリスクが伴います。',
            'economics.disclosureLink': '完全なトークンエコノミクスを読む',

