            'diligence.kicker': '形容詞ではなく、実際の作業を評価する',
            'diligence.title': 'すべての主張に、コードの裏づけがある。',
            'diligence.desc': 'TOSは、真剣な投資家にビジョンと実装済みのものを混同させることを求めません。まずソースコードから始め、現在の基盤を検証したうえで、サービスと端末のロードマップがそれをカテゴリーを定義するネットワークへと変えられるかどうかを評価してください。',
