            'agentEcosystem.desc': 'TOS는 개방적이고 벤더 중립적인 프로토콜을 기반으로 하나의 무상태(stateless) MCP 인터페이스와 하나의 A2A 인터페이스를 제공합니다. 두 표준 중 하나를 지원하는 에이전트 클라이언트라면 별도의 전용 SDK나 개별 통합 없이도 TOS 서비스를 바로 탐색·견적·호출할 수 있습니다. 우리는 이미 10억 개 이상의 에이전트를 맞이할 준비가 되어 있습니다.',

            'platform.kicker': 'TOS가 조정하는 것',
            'platform.title': '모든 에이전트가 거래에 사용할 수 있는 하나의 공통 문법.',
            'platform.desc': '클라이언트는 명시적인 가격, 지연시간, 프라이버시, 지역, 증빙 제약 아래에서 특정 역량을 요청합니다. 제공자는 이를 승인할지 결정합니다. TOS는 그 요청을 권한, 증명, 정산에 묶습니다.',
