            'flywheel.leverage1Title': '애플리케이션 계층은 자산 경량화',
            'flywheel.leverage1Desc': '제공자가 하드웨어에 투자하고 운영합니다. TOS는 시장 접근, 약정, 정산을 조정합니다.',
            'flywheel.leverage2Label': '확장 논리',
            'flywheel.leverage2Title': '하나의 기반 프로토콜, 여러 수직 영역',
            'flywheel.leverage2Desc': 'AI가 네트워크를 열고, 스토리지·상거래·도구·대인 서비스도 동일한 신뢰 레일을 재사용할 수 있습니다.',
            'flywheel.leverage3Label': '방어력',
