            'flywheel.leverage3Desc': '신원, 정책, 증빙, 적합성, 운영 이력은 엔드포인트와 하드웨어 세대를 넘어 이어집니다.',

            'foundation.kicker': '실행으로 뒷받침되는 신뢰성',
            'foundation.title': '실제로 작동하는 인프라. 모호한 경계는 없습니다.',
            'foundation.desc': '블록체인과 네트워킹 기반은 오늘 이미 오픈소스로 존재합니다. 서비스 프로토콜 계층과 단말 제품 계층은 의도적으로 분리되어 있으며, 다음 전달 대상으로 명확히 표시되어 있습니다.',
