            'economics.kicker': '고정 공급 정책',
            'economics.title': '공급량은 고정되고 밸리데이터만 발행합니다.',
            'economics.desc': 'TOS의 최대 총발행량은 500,000,000 TOS로 고정됩니다. 잠정적인 101,000 TOS 제네시스 밸리데이터 부트스트랩도 이 총량에 포함되며, 남은 499,899,000 TOS는 선출된 밸리데이터가 생성한 최종 확정 블록의 프로토콜 보상으로만 발행할 수 있습니다. 서비스 작업, 제공자 주장, 오프체인 점수는 TOS를 생성할 수 없습니다.',
            'economics.metric1Label': '고정 최대 총발행량',
            'economics.metric1Value': '5억 TOS',
            'economics.metric1Desc': '제네시스와 이후의 모든 밸리데이터 보상을 포함하는 컨센서스 하드캡입니다.',
            'economics.metric2Label': '잠정 제네시스',
            'economics.metric2Value': '101,000 TOS',
            'economics.metric2Desc': '10만 부트스트랩 자금에 더해 각 500 TOS의 시스템 예비금 두 건.',
            'economics.metric3Label': '제네시스 이후 밸리데이터 발행',
            'economics.metric3Value': '499,899,000 TOS',
            'economics.metric3Desc': '최종 확정 블록과 함께만 발행되며 기준 분배 기간은 약 7년입니다.',
            'economics.metric4Label': '내부자 배분',
            'economics.metric4Value': '0 TOS',
            'economics.metric4Desc': '팀, 투자자, 재단, 생태계, 재무 준비금에 대한 배분이 없습니다.',
            'economics.card1Label': '밸리데이터 보상이 만들어지는 방식',
            'economics.card1Title': '블록이 선출된 밸리데이터 집합에 자금을 공급합니다.',
            'economics.flow1': '생성된 블록',
            'economics.flow3': 'Elector 보너스 풀',
            'economics.flow4': '유효 스테이크 비율',
            'economics.card1Desc': '확정된 블록이 없으면 네이티브 발행도 없습니다. 장애가 발생해도 보상 부채, 캐치업 배수, 사후 보충은 생기지 않습니다. 거래 및 서비스 수수료는 기존 TOS를 이전하는 것이며, 블록 생성이 중단된 이후에도 계속됩니다.',
            'economics.card2Label': '제네시스가 제한되는 방식',
            'economics.card2Title': '부트스트랩 지갑은 일시적입니다.',
            'economics.card2Desc': '최초 4개 밸리데이터는 동일한 컨센서스 가중치로 시작합니다. 각 통제 지갑은 2만 TOS의 스테이킹 원금과, 계측된 부트스트랩 비용으로 최대 100 TOS까지 받을 수 있습니다. 연속된 두 차례의 선출 집합이 성공적으로 이어진 뒤에는 메인 지갑의 잔여 잔액을 소각하고 사용 가능 잔액을 0으로 만들어야 합니다.',
            'economics.card3Label': '집중도가 제한되는 방식',
            'economics.card3Title': '공개 선거가 행정적 배분을 대체합니다.',
            'economics.card3Desc': '균등한 부트스트랩 자금, 초기값 1의 유효 스테이크 계수, 제출 스테이크 한도, 반복되는 선거, 운영자 지배 구조 공개, 그리고 공개되는 집중도 지표는 모두 단일 주체의 지배력을 낮추도록 설계되었습니다. 4개 밸리데이터 집합은 시작 단계의 최소 요건일 뿐이며, 공개 참여 목표는 독립 운영자 64명, 장기 목표는 최소 75개의 자격을 갖춘 밸리데이터입니다.',
            'economics.card4Label': '발행이 종료되는 방식',
            'economics.card4Title': '고정 상한에 도달하면 발행을 중단합니다.',
            'economics.card4Desc': '제네시스 발행과 이후의 모든 밸리데이터 블록 보상은 5억 TOS 상한에 포함됩니다. 거버넌스는 보상률과 시기를 조정할 수 있지만 상한을 넘는 네이티브 발행을 승인할 수 없습니다. ConfigParam 14는 0으로 단계적으로 축소되거나 남은 공급 한도에서 잘려야 합니다.',
            'economics.disclosureTitle': '분배 통제는 집중 리스크를 낮추지만, 소유의 분산을 보장하지는 못합니다.',
            'economics.disclosureDesc': '초기 보상은 필연적으로 그 시점에 선출된 밸리데이터에게 돌아가며, 스테이크에 비례한 보상은 기존 보유량을 복리로 늘릴 수 있습니다. TOS는 지분, 부채, 배당, 상환, 고정 수익, 유동성, 가격 지지 중 어느 것도 제공하지 않습니다. 시장 가치는 하락할 수 있으며, 참여에는 기술적·커스터디·거버넌스·집중·규제 리스크가 따릅니다.',
            'economics.disclosureLink': '전체 토큰 이코노미 읽기',

            'roadmap.kicker': '초점을 맞춘 실행',
            'roadmap.title': '먼저 루프를 증명하고, 그다음 시장을 확장합니다.',
            'roadmap.desc': '어떤 단계도 순수 GPU 임대, 임의의 소비자용 실행, 또는 물리적 안전 시스템에 대한 블록체인 통제를 도입하지 않습니다.',
            'roadmap.item1Phase': '0단계',
            'roadmap.item1Title': '기반 프로토콜과 Edge Core',
            'roadmap.item1Desc': 'ARD 호환성, 카탈로그 게시, Registry 검색과 연합, 신원, 인증, 견적, 영수증, SDK, 적합성 검증.',
            'roadmap.item1State': '다음 기반 작업',
            'roadmap.item2Phase': '1단계',
            'roadmap.item2Title': '관리형 추론 단말',
            'roadmap.item2Desc': 'Tier 1 Linux/NVIDIA 레퍼런스, 승인된 모델, 제한된 스케줄링, 스트리밍, 계측, 영수증, 재시작 복구.',
            'roadmap.item2State': '첫 번째 수직 영역',
