            'roadmap.item3Title': 'OpenFox 자율 수익 창출 에이전트',
            'roadmap.item3Desc': '먼저 읽기 전용 스카우트 모드로 시작한 뒤, 보호된 테스트넷 작업을 거쳐, 작업 발견·위임·실행·정산 인터페이스가 적대적 검토를 통과한 후 제한된 프로덕션 자율성으로 진행합니다.',
