            'roadmap.item4Desc': 'Jetson/ARM 레퍼런스, 오프라인 작동, 안전한 업데이트, 실시간 우선순위, 액추에이터 격리, 단말 그룹 관리.',
            'roadmap.item4State': '엣지 확장',
