        'hero.eyebrow': '自主智能体的经济操作层',
        'hero.title': '智能体互联网的<br>开放系统。',
        'hero.lede': 'TOS 将互联网行为转化为有类型、可授权、可计量、可回执、可结算的操作，让独立智能体与服务提供方能够跨组织边界安全执行。',
        'hero.pillarLabel': '从意图到可问责的行动。',
        'hero.pillar1Label': '类型化',
