        'agentEcosystem.title': '贯穿智能体生态的一份经济契约',
        'agentEcosystem.desc': 'TOS 的目标是封装现有智能体与互联网接口，而不是取代它们。客户端可通过 ARD 发现服务，绑定 MCP、A2A、OpenAPI、HTTPS 或 RLDP，并在不同提供方之间沿用同一套能力、预算、计量、回执与结算语义。下方客户端仅用于说明 TOS 计划互操作的生态，不代表已完成集成或获得背书。',
