        'ard.tx3Title': '执行 + 证明',
        'ard.tx4Desc': '直接、托管、外部、退款、争议或拒绝',
        'ard.tx4Title': '结算 + 对账',
        'ard.value3Desc': '发现不会授权、预留硬件、转移资金、更新设备群或控制物理设备。每个有后果的交接都必须由所选协议和权限域验证。',
        'assets.card1Desc': 'Agent Account 区分所有者权限、受委托控制器权限、余额与支出策略。智能体只能在该有界委托内行动；它不会因此成为所有者或获得不受限制的密钥。',
        'assets.card1Label': '有界代理',
