        'assets.card2Desc': '精确的 Agreement 可选择按次、固定价、订阅、直接付款、Gift、托管或外部支付。支付事件只能证明其声明的权限所能证明的事实；它本身不证明交付、验收、利润或法律所有权。',
        'assets.card2Label': '多元商业',
        'assets.card2Title': '由 Agreement 选择价值如何流动。',
        'assets.card3Desc': '资源可被智能体访问之前，负责方必须描述资源、识别其所主张的控制者或提供者、定义条款和权限，并提供与主张相称的证据。TOS 可以锚定选定承诺；它不会把每一项描述或权利主张自动变成法律所有权。',
        'assets.card3Label': '可验证主张',
