        'assets.desc': '智能体只能在负责的所有者或组织所委托的权限内支出或赚钱。成熟的实现可发现报价、形成精确 Agreement，并使用所选支付路径，而不必为每个低风险动作询问人类。这是目标模型；生产级自治与外部需求仍需通过验收。',
        'assets.maturityBoundaryDesc': 'Agent Account 与当前 tos_service_v1 注册及商业工程已有本地证据。当前域的全新公共测试网权限、独立商业验收、重复外部需求和生产托管仍待验证。OpenFox 已完成同一主机上的八智能体有界实验，但这不是已部署的赚钱服务，也不证明外部利润。',
        'assets.tier2Desc': '将服务主张绑定到可验证身份、权限域、出处和 Capability 授权。链上记录证明被采纳的主张或控制状态，不会自动证明物理、知识产权或链下财产的法律所有权。',
        'assets.tier4Desc': '一致的 Agreement 可以要求签名证据和 Receipt。经验证的历史可供未来本地判断参考，但不会成为普适信誉，也不保证未来价值。',
        'assets.tiersDesc': '要让 Skill、数据集、模型、服务或设备可被智能体使用，必须完成四个可问责步骤。仅有发现和支付永远不能建立信任、权限、质量或所有权。',
        'assets.title': '智能体可以交易，负责的所有者保留权力。',
        'capability.card1Desc': '必须确认发布者、来源、不可变版本、摘要、许可证、依赖项与撤销状态。',
        'capability.card1Title': '固定身份与版本',
        'capability.card2Desc': 'Intent 内容、目录热度、模型输出或网络连通性永远不能决定凭据、目的地、签名路径或审批策略。',
        'capability.card2Title': '授予最小权限',
        'capability.card3Desc': '实验活动可以产生候选项，但在用于后果性行动前，必须由独立且针对该候选项的 PromotionAuthority 批准。',
        'capability.card3Title': '将学习与晋升分离',
        'capability.card4Desc': 'Web、iOS、Android、CLI 和外部签名器应展示精确 Intent 修订版、审批、报告、暂停、撤销、对账与恢复状态。',
        'capability.card4Title': '让所有者保持控制',
        'capability.desc': 'OpenFox 首先复用已精确准入的内置能力。若不匹配，则搜索所有者批准的 Skills 与 MCP 市场，验证候选项，在不接触生产秘密的环境中测试，并只授予最低权限。只有外部候选均不通过时，才开发隔离的本地候选能力。',
        'capability.title': '能力是否可信取决于证据，而不是格式或市场上架状态。',
        'closing.cta1': '阅读宪法',
        'closing.desc': '可撤销的 Intent，精确的 Agreement，有界权限，可验证证据，多元结算。',
        'closing.kicker': '更大互联网中的一个开放组成部分',
        'closing.title': '智能体在本地发现。<br>协议让承诺可移植。',
        'diligence.desc': '先查看宪法约束与规范性协议，再分别核验实现、独立验收、部署及最终状态证据。公开文字和同一主机测试不能替代外部需求或生产证明。',
        'diligence.link1Desc': '有关权限、选择、证据和制度学习的创始约束',
        'diligence.link1Title': 'Agentic Internet 宪法',
        'diligence.link2Desc': '当前权限、外部验收、重复需求与生产证据',
        'diligence.link2Title': '规范性交付门槛',
        'diligence.link3Desc': '软件工作切入点、通用 Intent 核心与 Profile 扩展标准',
        'diligence.link3Title': '产品策略',
        'diligence.link4Desc': '同主机八智能体证据、局限与下一阶段外部门槛',
        'diligence.link4Title': 'OpenFox 实验报告',
        'diligence.title': '每项主张，都由正确类型的证据支撑。',
        'economics.settlementBoundaryDesc': '互相信任的各方可以直接结算，Agreement 也可以选择外部轨道。只有明确选择 TOS 网络执行时，TOS 手续费、托管、保证金与最终性才适用。其他轨道的证据必须保留自身权限标签，不得称为 TOS 已最终确认。',
        'economics.settlementBoundaryTitle': '原生 TOS 是一种可选结算 Profile，而不是 Intent Commerce 协议的全部。',
        'faq.a1': '不是。TOS 为智能体工作提出可移植的 Intent 与 Agreement 语义：身份、权限、精确条款、执行、证据、Receipt、恢复与结算。框架和提供者可以独立实现这些语义。',
        'faq.a11': '不一定。互相信任的各方可以直接结算，Agreement 也可以选择外部轨道。只有所选 Profile 使用 TOS 网络执行、手续费、托管、保证金或最终结算时，才需要原生 TOS。其他轨道的证据不得称为 TOS 已最终确认。',
        'faq.a13': '所有者定义可访问的能力与数据、审批阈值、支出与风险限额、允许的交易对手和结算 Profile，以及暂停或撤销规则。承诺前可修改主导 Intent，执行中可监控，结果后可要求证据并对账；智能体不得悄然扩大自己的权限。',
        'faq.a14': '设计上可以。互操作性由已发布的语义、测试向量、一致性证据和 Profile 规则定义，而不是强制使用 TOS 仓库、OpenFox 运行时、模型、市场、数据库或区块链。复用权仍取决于各仓库明确的许可证；公开可见本身不是许可证。',
        'faq.q15': 'TOS 与 Bittensor 有什么区别？',
        'faq.a15': '两者处于 AI 经济的不同层。Bittensor 组织数字商品的生产：子网所有者定义矿工生产什么、验证者如何打分，协议排放奖励供给侧。TOS 组织 AI 服务的交易：智能体先绑定精确的 Agreement——范围、预算、期限、证据、追索——在受托限额内执行，凭签名 Receipt 结算，常规服务付款独立于协议发行。AIPoW 计分从已结算 Receipt 确定性地重算、可复现，而非主观投票；workchain 是执行分区而非激励市场。两个系统可以互补：子网生产的服务可以作为 TOS 能力被发布、购买与结算。',
        'faq.a3': 'ARD 可以提供公开且联邦化的发现界面。发现数据绝不是执行或结算权限：行动前仍必须验证身份、能力、实时条款、策略和精确 Agreement。',
        'faq.a4': '第一项商业证明是由互不关联的买方、提供方和验证方完成可机器检查的软件工作：发现、协商、绑定精确 Agreement、执行、核验证据、签发可移植 Receipt、安全恢复并结算。它需要在没有 AIPoW 奖励的情况下形成重复外部需求。',
        'faq.a5': 'tos_service_v1 工程基线与 OpenFox 有界本地赚钱闭环已经实现并测试。当前域的新权限证据、无关联方验收、重复外部需求、生产就绪以及更广泛的 Intent Commerce Profile 仍是待通过的证据门槛。',
        'faq.a6': '当独立实现共享可移植的 Intent、Agreement、Receipt、证据与一致性语义，提供方可替换，且重复需求促使第三方增加兼容能力时，网络效应才可能出现。',
        'faq.q14': '第三方可以不使用 TOS 或 OpenFox 代码而实现该协议吗？',
        'flywheel.desc': '首个外部验收目标是可机器检查的软件工作。当独立的买方、提供方、验证方和实现共享同一套 Agreement 与证据语义时，智能体可以比较报价、携带有界权限、核验结果并更换提供方，而无需把任何单一 Gateway 或市场变成事实来源。',
        'flywheel.leverage1Desc': '从一条可独立验证的完整生命周期开始：Intent、报价、Agreement、有界执行、证据、Receipt，以及跨无关联角色的结算。',
        'flywheel.leverage1Title': '可机器检查的软件工作',
        'flywheel.leverage2Desc': 'Intent 内容可以描述新行业而无需修改核心协议。只有权限、排序、隐私、准入或副作用确实不同，才新增 Profile。',
        'flywheel.leverage2Title': '通用核心，窄域 Profile',
        'flywheel.leverage3Desc': '持久价值来自独立实现、可移植证据、重复需求与可测可靠性，而不是强制锁定、单一市场或代币发行。',
        'flywheel.leverage3Title': '一致性与经验证历史持续复利',
        'flywheel.title': '公开规范，竞争实现，可移植证据。',
