        'governance.authorityDesc': '公开主张如何映射到宪法、规范、实现、部署及最终状态证据',
        'governance.authorityTitle': '主页内容权威规则',
        'governance.boundaryDesc': '治理地位需要明确公开记录，注明采纳机构、精确提交、日期、范围、修订路径和复审周期。',
        'governance.boundaryTitle': '发布不等于批准',
        'governance.constitutionDesc': '创始提案 · 尚未批准 · 对独立项目无管辖权',
        'governance.constitutionTitle': '阅读宪法',
        'governance.desc': '创始提案以 Ostrom 的多中心治理为主轴，并吸收 Hayek 的分布式知识、Coase 的交易成本、Simon 的有限理性与 North 的制度激励。它约束 TOS 管理者，同时让独立实现和机构自由治理各自正当的领域。',
        'governance.kicker': '宪法方向',
        'governance.reviewDesc': '已完成三轮内部完整性审核；不声称获得独立宪法、安全或法律批准',
        'governance.reviewTitle': '审查证据边界',
        'governance.title': '多中心治理是核心，而不是让单一市场、模型或链决定一切。',
        'governanceHome.boundaryDesc': '只有通过明确批准记录，并注明权限主体、精确提交、日期和采纳范围，宪法才获得治理地位。它的发布不约束独立项目。',
        'governanceHome.boundaryTitle': '提案不等于采纳',
        'governanceHome.constitutionDesc': '创始提案 · 已发布并完成内部审核 · 尚未批准',
        'governanceHome.constitutionTitle': 'Agentic Internet 宪法',
        'governanceHome.desc': 'TOS 为 Agentic Internet 提出多中心设计：决策留在具备能力且可问责的最低层级；共识只用于需要单一权威历史的事实；参与者保有真正的选择与退出；实验不得自行晋升为更大权力。',
        'governanceHome.kicker': '宪法方向',
        'governanceHome.openfoxDesc': '本地解释与有界执行；模型输出永远不是协议权威',
        'governanceHome.openfoxTitle': 'OpenFox 参考智能体',
        'governanceHome.specDesc': 'Schema、权限规则、不变量、Profile、向量与验收门槛',
        'governanceHome.specTitle': '规范性服务协议',
        'governanceHome.title': '本地判断，最小权限，可验证承诺。',
        'hero.cta1': '阅读宪法',
        'hero.cta2': '查看协议',
        'hero.eyebrow': '开放 Agentic Internet 的创始参考生态',
        'hero.lede': 'TOS 开发公共协议提案、参考实现与基础设施，使人类和智能体能够表达可撤销 Intent、形成精确 Agreement、在有界权限内行动、证明结果并选择结算路径。TOS 是 Agentic Internet 的一个开放组成部分，不是它的所有者或强制市场。',
        'hero.pillar1Label': '表达',
        'hero.pillar1Text': 'Intent 陈述期望结果，但不会悄然产生义务。',
        'hero.pillar2Label': '达成一致',
        'hero.pillar2Text': '精确接受的条款绑定参与方、权限、证据、救济与付款。',
        'hero.pillar3Label': '执行',
        'hero.pillar3Text': '智能体只能在已准入能力、策略、预算与稳定动作身份内行动。',
        'hero.pillar4Label': '问责',
        'hero.pillar4Text': '证据、Receipt、争议与结算始终绑定已接受的 Agreement。',
        'hero.pillarLabel': '从可撤销 Intent 到可问责行动。',
        'next.foundation': '区分工程实现、公共验收与生产验收。',
        'openfox.boundaryDesc': '已完成的实验使用八个逻辑智能体、两个本地 Intent Carrier 和同一故障域内的本地三节点 TOS 网络。内部转账在成本前净额为零。它证明开发闭环，不证明外部收入、独立运行、公共网络验收或生产就绪。在独立晋升控制建立前，赚钱、生产与后果性工作流仍禁止自动申请。',
        'openfox.eq1Desc': '定义版本化 Intent、Agreement、权限、动作身份、证据、Receipt、争议与结算语义。规范不是市场运营者。',
        'openfox.eq1Label': '01 · 共享语义',
        'openfox.eq2Desc': 'Skills、工具、数据或生产能力必须通过身份、版本、出处、权限、隔离与撤销检查后，才能提供。',
        'openfox.eq2Label': '02 · 已准入能力',
        'openfox.eq3Desc': '在所有者策略和精确接受的 Agreement 内进行本地解释、提出行动建议并协调已准入能力。',
        'openfox.kicker': '所有者指导的自主工作',
        'openfox.lede': 'OpenFox 已实现有界本地赚钱基线：可发现 Intent、评估机会、协调 Agreement、执行已准入能力、核对付款、报告证据，并产生可审核的学习候选项。这些实现证据不等于已部署的赚钱服务，也不证明外部利润。',
        'openfox.loop1Desc': '监视有界且保留出处的来源，在本地解释开放式需求。',
        'openfox.loop1Title': '发现 Intent',
        'openfox.loop2Desc': '验证身份与出处，匹配已准入能力，估算成本和风险，并提出精确条款。',
        'openfox.loop2Title': '评估 + 协商',
        'openfox.loop3Desc': '只有精确接受并获得策略授权后，才以稳定动作身份和批准目的地行动。',
        'openfox.loop3Title': '达成一致 + 执行',
        'openfox.loop4Desc': '提交约定证据，区分已观察与已最终确认的付款，核算利润与争议，并提出有界学习。',
        'openfox.loop4Title': '证据 + 对账',
        'openfox.state': '本地基线已实现 · 生产仍待验收',
        'openfox.title': '发现机会，提出行动，永不自行授予权力。',
        'platform.desc': '人类与智能体发布或交换 Intent，在本地解释、协商精确条款，并在后果性工作开始前形成 Agreement。Agreement 绑定权限、资源、证据、救济和所选结算域，无需把私有载荷或每次交互都放到链上。',
        'platform.flow1Desc': '表达带有出处与修订版的可撤销结果、机会或需求。',
        'platform.flow1Title': 'Intent',
        'platform.flow2Desc': '在本地解释、比较候选、交换报价并澄清重要条款。',
        'platform.flow2Title': '发现 + 协商',
        'platform.flow3Desc': '接受精确修订版，绑定参与方、范围、价格、权限、证据与救济。',
        'platform.flow3Title': '达成一致 + 授权',
        'platform.flow4Desc': '以稳定动作身份仅执行一次有界工作，并返回约定证据。',
        'platform.flow4Title': '执行 + 证明',
        'platform.flow5Desc': '按照 Agreement 完成直接、托管、Gift 或外部结算，或者争议或拒绝。',
        'platform.flow5Title': '结算 + 对账',
        'platform.kicker': 'Intent Commerce',
        'platform.principle1Desc': 'Intent、排名、对话、模型推断或界面操作不能悄然变成 Agreement、付款权限或执行命令。',
        'platform.principle1Title': 'Intent 不是权限',
