        'platform.principle3Title': '最低充分制度',
        'platform.principle4Desc': '签名记录将稳定动作与验收、会计、退款、争议及所选结算权限连接，而无需公开私有载荷。',
        'platform.principle4Title': '受 Agreement 约束的证据',
