        'roadmap.desc': '首个外部证明是由互不关联的买方、提供方和验证方，在精确 Agreement、执行、证据、Receipt、恢复和结算语义下完成可机器检查的软件工作，且不依赖 AIPoW 奖励。',
        'roadmap.item1Desc': '部署全新 tos_service_v1 对象，并在当前网络域复现注册、变更、撤销及严格多数的最终状态解析。',
