        'hero.lede': 'TOS は、人と Agent が取消可能な Intent を表明し、正確な Agreement を形成し、限定権限で行為し、成果を証明し、決済経路を選ぶための公開プロトコル提案、参照実装、インフラを開発します。TOS は Agentic Internet の一つのオープンな構成要素であり、その所有者や必須市場ではありません。',
