        'openfox.boundaryDesc': '완료된 캠페인은 동일 호스트 장애 도메인의 8개 논리 Agent, 2개 로컬 Intent Carrier, 3노드 TOS Network를 사용했고 비용 전 내부 이전 순액은 0이었습니다. 이는 개발 루프의 증거일 뿐 외부 수익, 독립 운영, 공개 네트워크 수락, 프로덕션 준비의 증거가 아닙니다. 독립 승격 통제가 생길 때까지 수익·프로덕션·중대한 워크플로의 자동 지원은 금지됩니다.',
